package com.hosteldekho.repository; import com.hosteldekho.entity.BookingRequest; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType; import java.util.*; public interface BookingRequestRepository extends JpaRepository<BookingRequest,Long>{@Query("select b from BookingRequest b join b.room r join r.hostel h where h.manager.id=:managerId order by b.createdAt desc") List<BookingRequest> findForManager(Long managerId); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select b from BookingRequest b join fetch b.room r join fetch r.hostel where b.id=:id") Optional<BookingRequest> findByIdForUpdate(@Param("id") Long id);}
